const API='https://api.gumroad.com/v2/products';
let memo=null;
export function publicProducts(items,hiddenId='') {
 if(!Array.isArray(items))throw new Error('Invalid catalog');
 return items.filter(p=>p&&!p.deleted&&p.published===true&&p.id!==hiddenId).flatMap(p=>{
  let url;try{url=new URL(p.short_url);}catch{return []}
  if(url.protocol!=='https:'||url.hostname!=='sirtraver.gumroad.com'||!url.pathname.startsWith('/l/'))return [];
  let image='';try{const u=new URL(p.thumbnail_url);if(u.protocol==='https:'&&['public-files.gumroad.com','gumroad-public-storage.s3.amazonaws.com'].includes(u.hostname))image=u.href}catch{}
  return [{id:p.id,title:String(p.name||'Recurso').slice(0,180),summary:String(p.custom_summary||'').slice(0,260),url:url.href,image,price:p.price===0?'Free · €0':String(p.formatted_price||''),published:p.published===true,demo:false}];
 });
}
export async function catalog(request,env,ctx,fetcher=fetch) {
 if(request.method!=='GET')return new Response(null,{status:405,headers:{Allow:'GET'}});
 const json=(body,status=200,headers={})=>Response.json(body,{status,headers:{'Cache-Control':'no-store',...headers}});
 if(!env.GUMROAD_ACCESS_TOKEN)return json({status:'unavailable',products:[]},503);
 const identity=env.GUMROAD_ACCESS_TOKEN+'|'+(env.GUMROAD_HIDDEN_PRODUCT_ID||'');
 if(memo&&memo.identity===identity&&memo.expires>Date.now())return json({status:'ok',products:memo.products},200,{'Cache-Control':'public, max-age=30'});
 try{
  const response=await fetcher(API,{headers:{Authorization:'Bearer '+env.GUMROAD_ACCESS_TOKEN,Accept:'application/json'},signal:AbortSignal.timeout(10000)});
  if(!response.ok)throw new Error('upstream');const data=await response.json();if(data.success!==true)throw new Error('upstream');
  const products=publicProducts(data.products,env.GUMROAD_HIDDEN_PRODUCT_ID||'Moy9nnuULBf1HQdRh3v_HA==');
  const out=json({status:'ok',products},200,{'Cache-Control':'public, max-age=30, s-maxage=60'});
  memo={identity,products,expires:Date.now()+60000};return out;
 }catch{return json({status:'unavailable',products:[]},503)}
}
export const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function launchState(es){return '<section class="launch-state"><span class="launch-badge">'+(es?'EN PREPARACIÓN':'IN THE MAKING')+'</span><h2>'+(es?'Próximamente: plantillas de Canva, Notion y recursos de diseño.':'Coming soon: Canva templates, Notion templates & design resources.')+'</h2><p>'+(es?'Recursos prácticos para diseñar mejor y trabajar con más claridad. Déjame tu email y te avisaré del lanzamiento.':'Practical resources for better design and clearer work. Leave your email and I’ll let you know when they launch.')+'</p><form class="launch-form"><label for="launch-email">Email</label><div class="launch-input"><input id="launch-email" name="email" type="email" autocomplete="email" required maxlength="254" placeholder="you@example.com"><button type="submit">'+(es?'Avisarme del lanzamiento':'Notify me at launch')+'</button></div><div class="form-trap" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="launch-consent"><input name="consent" type="checkbox" required> <span>'+(es?'Quiero recibir un email cuando se publiquen los recursos.':'I’d like an email when the resources launch.')+'</span></label><p class="launch-privacy">'+(es?'Tu email se usará solo para este aviso. Puedes pedir su eliminación mediante el icono de correo de la cabecera.':'Your email will only be used for this notification. To remove it, use the email icon in the header.')+'</p><p role="status" aria-live="polite"></p></form></section>'}
export function productPath(p,es=false){return (es?'/es':'')+'/resources/product/'+encodeURIComponent(new URL(p.url).pathname.split('/').at(-1))+'/'}
export function renderResources(products,language='en'){
 const es=language==='es';
 if(!products.length)return launchState(es);
 return products.map(p=>'<article class="project-card product-card">'+(p.image?'<img src="'+escape(p.image)+'" alt="'+(es?'Portada de ':'Cover of ')+escape(p.title)+'" width="600" height="600" loading="lazy">':'')+'<div class="card-caption"><h2>'+escape(p.title)+'</h2></div><p class="product-summary">'+escape(p.summary)+'</p><div class="product-bottom"><span>'+escape(es?p.price.replace('Free · €0','Gratis · 0 €'):p.price)+'</span><a href="'+productPath(p,es)+'">'+(es?'Ver recurso →':'View resource →')+'</a></div></article>').join('');
}
export function resourceSchema(products){return JSON.stringify({'@context':'https://schema.org','@type':'ItemList','name':'SIRTRAVER digital resources','itemListElement':products.filter(p=>p.published).map((p,i)=>({'@type':'ListItem','position':i+1,'item':{'@type':'CreativeWork','name':p.title,'url':'https://sirtraver.com'+productPath(p),'image':p.image,'creator':{'@id':'https://sirtraver.com/#javier-traver'}}}))}).replace(/</g,'\\u003c');}
let portfolioMemo=null;
const assetJson=path=>JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(assets[path][1]),c=>c.charCodeAt(0))));
const portfolioFallback=()=>assetJson('/assets/portfolio.json').projects;
const behanceState=html=>{const match=html.match(/<script[^>]*id="beconfig-store_state"[^>]*>([\s\S]*?)<\/script>/);if(!match)throw Error('Unavailable public profile');return JSON.parse(match[1])};
export function publicBehanceProjects(html){
 const items=behanceState(html)?.profile?.activeSection?.work?.profileProjects;
 if(!Array.isArray(items))throw Error('Unavailable public projects');
 return items.filter(p=>p.privacyLevel==='PUBLIC'&&p.publishStatus==='PUBLISHED'&&!p.isPrivate&&p.owners?.some(o=>o.username==='javiertraver')).flatMap(p=>{
  if(!Number.isSafeInteger(p.id)||p.id<=0)return [];
  let url;try{url=new URL(p.url)}catch{return []}
  if(url.protocol!=='https:'||url.hostname!=='www.behance.net'||!url.pathname.startsWith('/gallery/'+p.id+'/'))return [];
  const cover=p.covers?.allAvailable?.find(c=>c.width===808&&c.type==='WEBP')||p.covers?.allAvailable?.[0];let image='';try{const u=new URL(cover?.url);if(u.protocol==='https:'&&u.hostname==='mir-s3-cdn-cf.behance.net')image=u.href}catch{}
  return [{id:p.id,title:String(p.name||'Project').slice(0,180),url:url.href,href:'/projects/'+p.id+'/',publishedOn:Number(p.publishedOn)||0,image,category:/identity|identidad/i.test(p.name)?'Visual identity':'Visual design'}];
 }).sort((a,b)=>b.publishedOn-a.publishedOn).slice(0,60);
}
export async function portfolio(env,ctx={},fetcher=fetch){
 if(portfolioMemo&&portfolioMemo.expires>Date.now())return portfolioMemo;
 let saved;try{const object=await env.BUCKET?.get('catalog/behance.json');saved=object?await object.json():null}catch{}
 if(saved?.projects?.length&&saved.expires>Date.now()){portfolioMemo=saved;return saved}
 const refresh=async()=>{
  const response=await fetcher('https://www.behance.net/javiertraver',{headers:{'User-Agent':'Mozilla/5.0',Accept:'text/html'},signal:AbortSignal.timeout(7000)});
  if(!response.ok)throw Error('Behance unavailable');const html=await response.text();if(html.length>2000000)throw Error('Profile too large');const projects=publicBehanceProjects(html);if(!projects.length)throw Error('Empty public profile');
  const local=new Map(portfolioFallback().map(p=>[p.id,p]));
  const result={projects:projects.map(p=>({...local.get(p.id),...p,image:local.get(p.id)?.image||p.image})),source:'behance',updatedAt:new Date().toISOString(),expires:Date.now()+3600000};
  await env.BUCKET?.put('catalog/behance.json',JSON.stringify(result),{httpMetadata:{contentType:'application/json'}});portfolioMemo=result;return result;
 };
 if(saved?.projects?.length&&ctx.waitUntil){ctx.waitUntil(refresh().catch(()=>{}));return saved}
 try{return await refresh()}catch{portfolioMemo={projects:portfolioFallback(),source:'last-confirmed-import',updatedAt:'2026-10-12',expires:Date.now()+60000};return portfolioMemo}
}
export function projectTitle(project,es){return es?project.title.replace(/\s*[-–—]\s*Visual Identity/gi,' — Identidad visual').replace(/^Type in motion$/,'Tipografía en movimiento'):project.title}
export function renderPortfolio(projects,es){return '<section class="project-grid" aria-label="'+(es?'Proyectos de diseño':'Design projects')+'">'+projects.map(p=>'<a class="project-card" href="'+(es?'/es':'')+p.href+'"><img src="'+escape(p.image)+'" alt="'+escape(projectTitle(p,es))+'" width="808" height="632" loading="lazy"><div class="card-caption"><h3>'+escape(projectTitle(p,es))+'</h3><span aria-hidden="true">→</span></div><p>'+(es?(p.category==='Visual identity'?'Identidad visual':'Diseño visual'):p.category)+'</p></a>').join('')+'</section>'}
export async function projectMedia(project,env){
 if(project.media?.length)return project.media;
 const key='catalog/project-'+project.id+'.json';try{const stored=await env.BUCKET?.get(key);if(stored)return await stored.json()}catch{}
 try{
  const response=await fetch(project.url,{headers:{'User-Agent':'Mozilla/5.0'},signal:AbortSignal.timeout(7000)});if(!response.ok)throw Error();const source=await response.text();if(source.length>3000000)throw Error();const state=behanceState(source);const urls=new Set();
  const walk=(x,depth=0)=>{if(depth>20)return;if(typeof x==='string'){try{const u=new URL(x);if(u.protocol==='https:'&&u.hostname==='mir-s3-cdn-cf.behance.net'&&u.pathname.includes('/project_modules/'))urls.add(u.href)}catch{}}else if(Array.isArray(x))x.forEach(v=>walk(v,depth+1));else if(x&&typeof x==='object')Object.values(x).forEach(v=>walk(v,depth+1))};walk(state.project||state);
  const media=[...urls].slice(0,80).map(src=>({src}));if(media.length){await env.BUCKET?.put(key,JSON.stringify(media));return media}
 }catch{}
 return [{src:project.image,width:808,height:632}];
}
export function renderProject(project,media,es){
 const narrative=assetJson('/assets/cases.json')[String(project.id)]?.[es?'es':'en'];const labels=es?['Reto','Concepto','Proceso','Solución','Resultado']:['Challenge','Concept','Process','Solution','Result'];
 const image=(m,i)=>'<img src="'+escape(m.src)+'" alt="'+escape(projectTitle(project,es))+' · '+(es?'pieza':'visual')+' '+(i+1)+'" '+(m.width?'width="'+m.width+'" height="'+m.height+'"':'')+' loading="'+(i?'lazy':'eager')+'">';
 const gallery='<div class="project-gallery">'+media.slice(narrative?1:0).map((m,i)=>image(m,i+(narrative?1:0))).join('')+'</div>';
 const story=narrative?'<section class="case-story">'+narrative.map((text,i)=>'<section id="case-'+i+'"><span>0'+(i+1)+'</span><div><h2>'+labels[i]+'</h2><p>'+escape(text)+'</p></div></section>').join('')+'</section>':'';
 const hero=narrative&&media[0]?'<div class="case-hero">'+image(media[0],0)+'</div>':'';
 return '<a class="back-link" href="'+(es?'/es/':'/')+'">← '+(es?'Volver a proyectos':'Back to projects')+'</a><header class="project-heading"><p class="overline">'+(es?(project.category==='Visual identity'?'IDENTIDAD VISUAL':'DISEÑO VISUAL'):project.category.toUpperCase())+'</p><h1>'+escape(projectTitle(project,es))+'</h1><p>Javier Traver · '+new Date(project.publishedOn*1000).getUTCFullYear()+'</p></header>'+hero+(narrative?'<nav class="case-nav" aria-label="'+(es?'Secciones del proyecto':'Project sections')+'">'+labels.map((label,i)=>'<a href="#case-'+i+'">'+label+'</a>').join('')+'</nav>':'')+story+gallery;
}
const waitlistHash=async value=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))).map(b=>b.toString(16).padStart(2,'0')).join('');
export async function subscribe(request,env){
 const reply=(status,code)=>Response.json({status:code},{status,headers:{'Cache-Control':'no-store','X-Robots-Tag':'noindex'}});
 if(request.method!=='POST')return reply(405,'method_not_allowed');
 if(request.headers.get('Origin')!==new URL(request.url).origin)return reply(403,'forbidden');
 if(!request.headers.get('Content-Type')?.startsWith('application/json')||Number(request.headers.get('Content-Length')||0)>2048)return reply(400,'invalid');
 let data;try{const text=await request.text();if(text.length>2048)return reply(400,'invalid');data=JSON.parse(text)}catch{return reply(400,'invalid')}
 const email=String(data.email||'').trim().toLowerCase();
 if(data.website)return reply(200,'subscribed');
 if(data.consent!==true||email.length>254||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return reply(400,'invalid');
 if(!env.BUCKET)return reply(503,'unavailable');
 try{
  const key='waitlist/'+await waitlistHash(email)+'.json';
  const existing=await env.BUCKET.get(key);
  if(!existing)await env.BUCKET.put(key,JSON.stringify({email,language:data.language==='es'?'es':'en',subscribedAt:new Date().toISOString(),consent:'Notify me when sirtraver resources launch',source:'sirtraver.com/resources'}),{httpMetadata:{contentType:'application/json'}});
  return reply(200,'subscribed');
 }catch{return reply(503,'unavailable')}
}
export async function waitlistAdmin(request,env){
 const headers={'Cache-Control':'no-store','X-Robots-Tag':'noindex'};
 if(!env.WAITLIST_ADMIN_TOKEN||request.headers.get('Authorization')!=='Bearer '+env.WAITLIST_ADMIN_TOKEN)return new Response('Not found',{status:404,headers});
 if(!env.BUCKET)return Response.json({status:'unavailable'},{status:503,headers});
 if(request.method==='POST'){
  const key='system/waitlist-storage-check.json';const check={status:'ready',checkedAt:new Date().toISOString()};await env.BUCKET.put(key,JSON.stringify(check));const object=await env.BUCKET.get(key);const read=await object?.json();
  return Response.json({status:read?.checkedAt===check.checkedAt?'ready':'unavailable'},{headers});
 }
 if(request.method!=='GET')return new Response(null,{status:405,headers});
 const records=[];let cursor;
 do{const page=await env.BUCKET.list({prefix:'waitlist/',limit:1000,cursor});for(const item of page.objects){const object=await env.BUCKET.get(item.key);if(object)records.push(await object.json())}cursor=page.truncated?page.cursor:undefined}while(cursor);
 const csv=value=>'"'+String(value||'').replace(/"/g,'""')+'"';
 return new Response('email,language,subscribed_at,consent\r\n'+records.map(r=>[r.email,r.language,r.subscribedAt,r.consent].map(csv).join(',')).join('\r\n'),{headers:{...headers,'Content-Type':'text/csv; charset=utf-8','Content-Disposition':'attachment; filename="sirtraver-launch-list.csv"'}});
}
const redirects={'/portfolio':'/','/portfolio/':'/','/es/portfolio':'/es/','/es/portfolio/':'/es/','/recursos':'/resources/','/recursos/':'/resources/','/recursos/brief-claro':'/resources/','/recursos/brief-claro/':'/resources/','/sobre-mi':'/about/','/sobre-mi/':'/about/'};
export default {
 async fetch(request,env,ctx){
  const u=new URL(request.url);
  if(u.pathname==='/api/waitlist-admin')return waitlistAdmin(request,env);
  if(u.pathname==='/api/subscribe')return subscribe(request,env);
  if(!['GET','HEAD'].includes(request.method))return new Response(null,{status:405,headers:{Allow:'GET, HEAD'}});
  if(u.hostname==='sirtraver.sirtraver.chatgpt.site'||u.hostname==='www.sirtraver.com'){u.hostname='sirtraver.com';return Response.redirect(u.href,301);}
  if(u.pathname==='/api/catalogo-gumroad'){const r=await catalog(request,env,ctx);r.headers.set('X-Robots-Tag','noindex');return r;}
  if(u.pathname==='/sitemap.xml'){const data=await portfolio(env,ctx);const base=new TextDecoder().decode(Uint8Array.from(atob(assets['/sitemap.xml'][1]),c=>c.charCodeAt(0)));const entries=data.projects.map(p=>{const en='https://sirtraver.com'+p.href;const es='https://sirtraver.com/es'+p.href;return [en,es].map(url=>'<url><loc>'+escape(url)+'</loc><xhtml:link rel="alternate" hreflang="en" href="'+en+'"/><xhtml:link rel="alternate" hreflang="es" href="'+es+'"/></url>').join('')}).join('');return new Response(request.method==='HEAD'?null:base.replace('</urlset>',entries+'</urlset>'),{headers:{'Content-Type':'application/xml; charset=utf-8','Cache-Control':'public, max-age=300'}});}
  if(u.pathname==='/api/portfolio'){const data=await portfolio(env,ctx);return Response.json({status:'ok',source:data.source,updatedAt:data.updatedAt,projects:data.projects},{headers:{'Cache-Control':'public, max-age=60','X-Robots-Tag':'noindex'}});}
  let path;try{path=decodeURIComponent(u.pathname)}catch{return new Response('Not found',{status:404,headers:{'X-Robots-Tag':'noindex'}})}
  if(path.endsWith('/index.html')){const destination=path.slice(0,-10);return Response.redirect(new URL(redirects[destination]||destination,u).href,301);}
  if(redirects[path])return Response.redirect(new URL(redirects[path],u).href,301);
  if(path.includes('..'))return new Response('Not found',{status:404,headers:{'X-Robots-Tag':'noindex'}});
  if(!path.endsWith('/')&&assets[path+'/index.html'])return Response.redirect(new URL(path+'/',u).href,301);
  const projectRoute=path.match(/^\/(es\/)?projects\/(\d+)\/$/);
  const productRoute=path.match(/^\/(es\/)?resources\/product\/([^/]+)\/$/);
  if(projectRoute){const es=!!projectRoute[1];const data=await portfolio(env,ctx);const project=data.projects.find(p=>String(p.id)===projectRoute[2]);if(project){const media=await projectMedia(project,env);return detailResponse(request,es,path,projectTitle(project,es),es?'Proyecto de diseño visual de Javier Traver.':'A visual design project by Javier Traver.',renderProject(project,media,es),{'@type':'CreativeWork','name':projectTitle(project,es),'image':project.image,'creator':{'@id':'https://sirtraver.com/#javier-traver'}})}}
  if(productRoute){const es=!!productRoute[1];const r=await catalog(new Request(request.url),env,ctx);const data=await r.json();const product=data.products.find(p=>productPath(p,es)===path);if(product){const iframeUrl=product.url+'?embed=true';const content='<a class="back-link" href="'+(es?'/es':'')+'/resources/">← '+(es?'Volver a recursos':'Back to resources')+'</a><header class="project-heading"><h1>'+escape(product.title)+'</h1><p>'+escape(product.summary)+'</p></header><iframe class="product-embed" src="'+escape(iframeUrl)+'" title="'+escape(product.title)+'" loading="lazy"></iframe><script src="/assets/product-embed.js" defer></script>';return detailResponse(request,es,path,product.title,product.summary,content,{'@type':'CreativeWork','name':product.title,'image':product.image,'creator':{'@id':'https://sirtraver.com/#javier-traver'}})}}
  if(path==='/project-template.html'||path==='/es/project-template.html')path='/not-public-template';
  if(path.endsWith('/'))path+='index.html';
  const item=assets[path];if(!item)return new Response('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page not found | SIRTRAVER</title><link id="sirtraver-favicon" rel="icon" type="image/png" sizes="32x32" href="data:image/png;base64,"><meta name="robots" content="noindex"><link rel="stylesheet" href="/assets/site.css"></head><body><main class="not-found"><h1>404</h1><p>This page could not be found.</p><a href="/">Back to SIRTRAVER</a></main></body></html>',{status:404,headers:{'Content-Type':'text/html; charset=utf-8','X-Robots-Tag':'noindex'}});
  const [type,b64]=item;const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));let body=bytes;
  if(path==='/index.html'||path==='/es/index.html'){const data=await portfolio(env,ctx);body=new TextDecoder().decode(bytes).replace(/<!--portfolio-->.*?<!--\/portfolio-->/s,renderPortfolio(data.projects,path.startsWith('/es/')));}
  if(path==='/resources/index.html'||path==='/es/resources/index.html'){
   const language=path.startsWith('/es/')?'es':'en';
   const response=await catalog(new Request(request.url,{method:'GET'}),env,ctx);const data=await response.json();
   const html=new TextDecoder().decode(bytes);const content=data.status==='ok'?renderResources(data.products,language):'<p class="catalog-status">'+(language==='es'?'El catálogo no está disponible temporalmente. Inténtalo de nuevo en unos instantes.':'The catalog is temporarily unavailable. Please try again shortly.')+'</p>';
   body=html.replace(/<!--resources-->.*?<!--\/resources-->/s,content);
   if(data.status==='ok')body=body.replace('</head>','<script type="application/ld+json">'+resourceSchema(data.products)+'</script></head>');
  }
  return new Response(request.method==='HEAD'?null:body,{headers:{'Content-Type':type,'Cache-Control':type.startsWith('text/html')?'no-cache':'public, max-age=300','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin'}});
 }
};

function detailResponse(request,es,path,title,description,content,entity){
 const template=assets[es?'/es/project-template.html':'/project-template.html'];let html=new TextDecoder().decode(Uint8Array.from(atob(template[1]),c=>c.charCodeAt(0)));
 const canonical='https://sirtraver.com'+path;const english=canonical.replace('https://sirtraver.com/es/','https://sirtraver.com/');const spanish='https://sirtraver.com/es/'+english.slice('https://sirtraver.com/'.length);
 html=html.replace(/<title>.*?<\/title>/,'<title>'+escape(title)+' | sirtraver</title>').replace(/<meta name="description" content="[^"]*">/,'<meta name="description" content="'+escape(description)+'">').replace(/<link rel="canonical"[^>]*>/,'<link rel="canonical" href="'+canonical+'">').replace(/<link rel="alternate" hreflang="en"[^>]*>/,'<link rel="alternate" hreflang="en" href="'+english+'">').replace(/<link rel="alternate" hreflang="es"[^>]*>/,'<link rel="alternate" hreflang="es" href="'+spanish+'">').replace(/<link rel="alternate" hreflang="x-default"[^>]*>/,'<link rel="alternate" hreflang="x-default" href="'+english+'">');
 html=html.replace(/<meta property="og:title"[^>]*>/,'<meta property="og:title" content="'+escape(title)+' | sirtraver">').replace(/<meta property="og:description"[^>]*>/,'<meta property="og:description" content="'+escape(description)+'">').replace(/<meta property="og:url"[^>]*>/,'<meta property="og:url" content="'+canonical+'">').replace(/<meta name="twitter:title"[^>]*>/,'<meta name="twitter:title" content="'+escape(title)+' | sirtraver">').replace(/<meta name="twitter:description"[^>]*>/,'<meta name="twitter:description" content="'+escape(description)+'">');
 html=html.replace(/<script type="application\/ld\+json">.*?<\/script>/s,'<script type="application/ld+json">'+JSON.stringify({'@context':'https://schema.org',...entity,url:canonical}).replace(/</g,'\\u003c')+'</script>');
 html=html.replace('<!--project-detail-->',content).replace('href="/es/about/" lang="es"','href="'+spanish.replace('https://sirtraver.com','')+'" lang="es"').replace('href="/about/" lang="en"','href="'+english.replace('https://sirtraver.com','')+'" lang="en"');
 return new Response(request.method==='HEAD'?null:html,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-cache','X-Content-Type-Options':'nosniff'}})
}
